import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    order_info = {}  # id -> dict(side, price, qty, active)
    seq_counter = 0

    def add_to_book(oid, side, price, qty, seq):
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = order_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        oid = order[1]
        side = order[2]

        if typ == 'limit':
            price = order[3]
            qty = order[4]
        elif typ == 'ioc':
            price = order[3]
            qty = order[4]
        elif typ == 'market':
            qty = order[3]
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1

        remaining = qty
        info = {'side': side, 'price': price, 'qty': remaining, 'active': True, 'seq': seq}
        order_info[oid] = info

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            if not opp_heap:
                break
            top = opp_heap[0]
            if side == 'buy':
                resting_price = top[0]
            else:
                resting_price = top[0]
            resting_seq = top[1]
            resting_id = top[2]

            resting_info = order_info.get(resting_id)
            if resting_info is None or not resting_info['active'] or resting_info['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            actual_resting_price = resting_info['price']

            if typ != 'market':
                if side == 'buy':
                    if actual_resting_price > price:
                        break
                else:
                    if actual_resting_price < price:
                        break

            heapq.heappop(opp_heap)

            trade_qty = min(remaining, resting_info['qty'])
            if side == 'buy':
                buy_id = oid
                sell_id = resting_id
            else:
                buy_id = resting_id
                sell_id = oid

            trades.append([buy_id, sell_id, actual_resting_price, trade_qty])

            remaining -= trade_qty
            resting_info['qty'] -= trade_qty

            if resting_info['qty'] > 0 and resting_info['active']:
                add_to_book(resting_id, resting_info['side'], resting_info['price'], resting_info['qty'], resting_info['seq'])
            else:
                resting_info['active'] = False

        info['qty'] = remaining

        if typ == 'limit':
            if remaining > 0:
                add_to_book(oid, side, price, remaining, seq)
            else:
                info['active'] = False
        else:
            info['active'] = False

    return trades

